"""Run the test suite and compute the QA matrix from evidence on disk.
Writes paper/generated/{test_results,test_log,qa_rows}.tex and results/qa_matrix.{json,md}."""
import json, os, re, subprocess, glob, sys
import pandas as pd

OUT = 'paper/generated'
tex = lambda s: str(s).replace('\\', '/').replace('_', '\\_').replace('%', '\\%').replace('&', '\\&').replace('#', '\\#')

# ---------------------------------------------------------------- pytest
r = subprocess.run([sys.executable, '-m', 'pytest', '-q', '-rA', '-p', 'no:cacheprovider', 'tests'], capture_output=True, text=True)
log = r.stdout.strip().splitlines()
summ = [l for l in log if re.search(r'\d+ passed|failed', l)][-1]
npass = int(re.search(r'(\d+) passed', summ).group(1)) if 'passed' in summ else 0
nfail = int(re.search(r'(\d+) failed', summ).group(1)) if 'failed' in summ else 0
names = [l.split(' ', 1)[1] for l in log if l.startswith('PASSED ') or l.startswith('FAILED ')]
open('results/pytest.log', 'w').write(r.stdout)
app = json.load(open('results/apptest.json')) if os.path.exists('results/apptest.json') else None
audit = json.load(open('results/leakage_audit.json'))
_rh, _ms = audit['radhar'], audit['milipoint']['subject']
audit['checks'] = [{'pass': v} for v in [
    sum(_rh['recording_overlap'].values()) == 0, not _rh['duplicate_recordings_any_split'],
    sum(_rh['identical_frames'].values()) == 0, sum(_rh['window_recording_overlap'].values()) == 0,
    bool(_rh['intensity_stats_train_only']['match']), not any(_ms['subject_overlap'].values()),
    sum(_ms['shared_frames'].values()) == 0, _ms['fraction_test_frames_seen_in_training'] == 0,
    audit['model_selection']['runs_checked'] > 0 and audit['model_selection']['consistent'] == audit['model_selection']['runs_checked']]]

open(f'{OUT}/test_results.tex', 'w').write('\n'.join([
    '\\begin{table}[h]', '\\centering', '\\caption{Test results (generated by \\texttt{scripts/make\\_qa.py}).}', '\\label{tab:testresults}',
    '\\begin{tabular}{lrr}', '\\toprule', 'Suite & Passed & Failed \\\\', '\\midrule',
    f'Unit / data / integration (\\texttt{{pytest tests/}}) & {npass} & {nfail} \\\\',
    (f'Demo application (\\texttt{{scripts/apptest\\_demo.py}}, {app["n_steps"]} interaction steps) & {app["n_steps"] - app["n_failed"]} & {app["n_failed"]} \\\\' if app else ''),
    f'Leakage audit checks (\\texttt{{scripts/leakage\\_audit.py}}) & {sum(1 for c in audit.get("checks", []) if c.get("pass"))} & {sum(1 for c in audit.get("checks", []) if not c.get("pass"))} \\\\',
    '\\bottomrule', '\\end{tabular}', '\\end{table}',
    'The demo test drives the real application headlessly: it loads both exported models, every bundled test sample '
    'and every perturbation condition, and fails on any exception or error message shown to the user.']))
open(f'{OUT}/test_log.tex', 'w').write('\\begin{lstlisting}[numbers=none,basicstyle=\\ttfamily\\scriptsize]\n' +
                                        '\n'.join(l[:110] for l in log if l.strip()) + '\n\\end{lstlisting}\n')

# ---------------------------------------------------------------- QA matrix
df = pd.read_csv('results/all_runs.csv')
ex = lambda *p: all(os.path.exists(x) for x in p)
nseed = lambda g: int((df.group == g).sum())
grp = set(df.group)
rob = {d: os.path.exists(f'results/robustness_{d}.csv') for d in ['radhar', 'milipoint']}
rcsv = pd.read_csv('results/robustness_milipoint.csv') if rob['milipoint'] else None
pend = subprocess.run(['grep', '-rl', '--exclude=qa_rows.tex', 'PENDINGTEXT', 'paper/generated', 'paper/sections', 'report/chapters'], capture_output=True, text=True).stdout.split()
hist_ok = all(set(['train_loss', 'val_loss', 'train_acc', 'val_acc', 'lr']) <= set(pd.read_csv(h).columns) for h in glob.glob('results/runs/*/history.csv'))
bundle = 'checkpoints/stpt_lite_radhar'
nbib = len(re.findall(r'^@', open('paper/refs.bib').read(), re.M))
years = [int(y) for y in re.findall(r'year\s*=\s*\{?(\d{4})', open('paper/refs.bib').read())]
baselines = [b for b in ['pointnet', 'pointnet_lstm', 'pointnet2', 'dgcnn', 'pointtransformer', 'voxel_tdcnn'] if 'rh_' + b in grp]
st = lambda ok: 'PASS' if ok else 'FAIL'
Q = [
    ('C1 Literature', f'$\\geq$15 papers 2022--26 ({sum(y >= 2022 for y in years)} of {nbib} references)', 'paper/refs.bib', st(sum(y >= 2022 for y in years) >= 15)),
    ('C1 Gap', 'Research gap and contributions stated', 'paper Sec. I--II', st('contribution' in open('paper/sections/intro.tex').read().lower())),
    ('C2 Datasets', 'Both datasets parsed and used', 'results/eda\\_stats.json', st(ex('results/eda_stats.json') and any(g.startswith('rh_') for g in grp) and any(g.startswith('mp_') for g in grp))),
    ('C2 EDA', 'EDA and pre-processing figures', 'figures/eda\\_*, preproc\\_*', st(ex('figures/eda_radhar.pdf', 'figures/eda_milipoint.pdf', 'figures/preproc_before_after.pdf'))),
    ('C2 Leakage', 'Automated audit: splits disjoint, train-only statistics', 'docs/leakage\\_audit.md', st(all(c.get('pass') for c in audit.get('checks', [])) and ex('docs/leakage_audit.md'))),
    ('C3 Model', 'Proposed model implemented, diagram', 'src/models.py, figures/arch.pdf', st(ex('figures/arch.pdf') and 'class STPTLite' in open('src/models.py').read())),
    ('C4 Baselines', f'$\\geq$3 baselines incl. SOTA ({len(baselines)} re-trained)', 'results/summary\\_radhar.csv', st(len(baselines) >= 3)),
    ('C4 Seeds', f'Proposed model, 3 seeds per dataset ({nseed("rh_stpt_lite_kd_robust")}/{nseed("mp_stpt_lite_kd_robust")})', 'results/all\\_runs.csv', st(nseed('rh_stpt_lite_kd_robust') >= 3 and nseed('mp_stpt_lite_kd_robust') >= 3)),
    ('C4 Statistics', 'McNemar (Holm) and bootstrap CI', 'results/stats.json', st(ex('results/stats.json'))),
    ('C4 Cross-dataset', 'MiliPoint$\\rightarrow$RadHAR transfer', 'results/summary\\_transfer.csv', st(any('mpinit' in g for g in grp))),
    ('C4 Ablation', 'Component ablation', 'results/summary\\_ablation.csv', st(sum(g.startswith('rh_abl_') for g in grp) >= 5)),
    ('Robustness', '7 perturbation types, 3 severities, both datasets', 'results/robustness\\_*.csv', st(all(rob.values()) and (rcsv is None or rcsv.condition.nunique() >= 8))),
    ('Training', 'Loss/accuracy/LR logged every epoch for every run', 'results/runs/*/history.csv', st(hist_ok)),
    ('Metrics', 'Accuracy, macro P/R/F1, per-class, top-3, latency, size', 'metrics.json', st(all(k in json.load(open(f'{bundle}/metrics.json')) for k in ['test', 'test_per_class', 'latency_ms_cpu1']))),
    ('C5 XAI', 'Attention, occlusion, saliency, t-SNE', 'results/xai.json', st(ex('results/xai.json', 'figures/xai_temporal.pdf', 'figures/tsne.pdf'))),
    ('Checkpoint', 'Exported model + inference script', 'checkpoints/, src/inference.py', st(ex(f'{bundle}/model.pt', f'{bundle}/bundle.json', 'checkpoints/stpt_lite_milipoint/model.pt'))),
    ('Tests', f'pytest ({npass} passed, {nfail} failed)', 'results/pytest.log', st(nfail == 0 and npass > 0)),
    ('C7 Demo', f'Streamlit demo, headless test ({app["n_steps"] if app else 0} steps, {app["n_failed"] if app else "?"} failed)', 'results/apptest.json', st(app is not None and app['n_failed'] == 0)),
    ('C7 Demo video', 'Screen recording of the live demo', 'figures/demo/demo.mp4', st(ex('figures/demo/demo.mp4'))),
    ('Config', 'Hyper-parameters in a config file', 'configs/default.yaml', st(ex('configs/default.yaml'))),
    ('Documentation', 'README, DEVLOG, reproduction script', 'README.md, docs/', st(ex('README.md', 'docs/DEVLOG.md', 'scripts/run_all.sh'))),
    ('No placeholders', 'No pending text in paper or report sources', 'placeholder grep', st(not pend)),
]
for name, path in [('C6 Paper', 'paper/main.pdf'), ('Report', 'report/report.pdf'), ('C7 Slides', 'presentation/Team10_mmWave_HAR.pptx')]:
    Q.append((name, 'Compiled / built and inspected page by page', tex(path), st(ex(path))))
open(f'{OUT}/qa_rows.tex', 'w').write('\n'.join(f'{a} & {b} & {{\\footnotesize\\ttfamily {c.replace("/", "/\\allowbreak{}").replace("_", "_\\allowbreak{}")}}} & \\textbf{{{d}}} \\\\' for a, b, c, d in Q))
json.dump([dict(area=a, check=b, evidence=c, status=d) for a, b, c, d in Q], open('results/qa_matrix.json', 'w'), indent=1)
open('results/qa_matrix.md', 'w').write('| Area | Check | Evidence | Status |\n|---|---|---|---|\n' +
                                        '\n'.join(f'| {a} | {re.sub(r"[$\\\\]|ensuremath", "", b).replace("geq", "≥").replace("rightarrow", "→")} | {c.replace(chr(92), "")} | {d} |' for a, b, c, d in Q))
print(summ); print([q for q in Q if q[3] != 'PASS'])
